package com.yuewei.plm.module.partner;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static com.yuewei.plm.module.partner.PartnerValues.*;

class PartnerCatalogFieldsTest {
 @Test void newSupplierQuoteDefaultsCnyWithoutPretendingItWasInTheOriginal(){var result=PartnerCatalogFields.normalize(Map.of(),Map.of("currency","","unitPrice","12"),true);assertEquals("CNY",result.get("currency"));assertEquals("business_default",result.get("currencySource"));assertEquals("",map(result.get("rawQuoteFields")).get("currency"));}
 @Test void explicitForeignCurrencyIsNeverReplacedByTheDefault(){var result=PartnerCatalogFields.normalize(Map.of(),Map.of("currency","USD"),true);assertEquals("USD",result.get("currency"));assertEquals("explicit",result.get("currencySource"));}
 @Test void aReadOfUnclassifiedHistoricalDataDoesNotWriteOrAssumeCny(){var raw=Map.<String,Object>of("currency","","moq","原文待确认");var result=PartnerCatalogFields.project(raw);assertEquals("",result.get("currency"));assertEquals("historical_unknown",result.get("currencySource"));assertEquals(2,raw.size());}
 @Test void exactSourceMoqIsSplitIntoIndependentFieldsButKeepsTheOriginal(){var result=PartnerCatalogFields.normalize(Map.of(),Map.of("moq","20个/每颜色型号"),true);assertEquals("20",result.get("moqQuantity"));assertEquals("个",result.get("moqUnit"));assertEquals("每型号每颜色",result.get("moqScope"));assertEquals("20个/每颜色型号",map(result.get("rawQuoteFields")).get("moq"));}
 @Test void ambiguousMoqStaysAsANoteAndDoesNotTurnIntoAQuantity(){var result=PartnerCatalogFields.normalize(Map.of(),Map.of("moq","20起，混批另议"),true);assertEquals("",result.get("moqQuantity"));assertEquals("20起，混批另议",result.get("moqNote"));assertEquals("",result.get("priceUnit"));}
 @Test void anEngineerCanEnterEachUnitAndConditionIndependently(){var result=PartnerCatalogFields.normalize(Map.of(),Map.of("priceUnit","套","moqQuantity","100.00","moqUnit","套","moqScope","每型号","moqNote","可混色"),true);assertEquals("100",result.get("moqQuantity"));assertEquals("套",result.get("priceUnit"));assertEquals("每型号",result.get("moqScope"));}
 @Test void zeroNegativeAndNonNumericMoqCannotMasqueradeAsKnownMinimums(){for(String value:List.of("0","-1","不限"))assertThrows(RuntimeException.class,()->PartnerCatalogFields.normalize(Map.of(),Map.of("moqQuantity",value),true));}
 @Test void laterExplicitUsdKeepsTheOriginalBlankCurrencyEvidence(){var first=PartnerCatalogFields.normalize(Map.of(),Map.of("currency",""),true);var result=PartnerCatalogFields.normalize(first,Map.of("currency","USD"),true);assertEquals("USD",result.get("currency"));assertEquals("explicit",result.get("currencySource"));assertEquals("",map(result.get("rawQuoteFields")).get("currency"));}
 @Test void theClientCannotForgeRawEvidenceOrAnExplicitDefaultMarker(){var result=PartnerCatalogFields.normalize(Map.of(),Map.of("currency","USD","currencySource","business_default","rawQuoteFields",Map.of("currency","CNY")),true);assertEquals("explicit",result.get("currencySource"));assertEquals("USD",map(result.get("rawQuoteFields")).get("currency"));}
 @Test void firstHistoricalEditCapturesPreviousValuesNotTheReplacement(){var result=PartnerCatalogFields.normalize(Map.of("currency","USD","moq","20个/每型号","unitPrice","5"),Map.of("currency","MXN","unitPrice","6"),true);assertEquals("USD",map(result.get("rawQuoteFields")).get("currency"));assertEquals("5",map(result.get("rawQuoteFields")).get("unitPrice"));}
 @Test void derivedMoqTracksAnExplicitOriginalTextCorrection(){var first=PartnerCatalogFields.normalize(Map.of(),Map.of("moq","20个/每型号每颜色"),true);var result=PartnerCatalogFields.normalize(first,Map.of("moq","100个/每型号每颜色"),true);assertEquals("100",result.get("moqQuantity"));assertEquals("20个/每型号每颜色",map(result.get("rawQuoteFields")).get("moq"));}
 @Test void anExplicitMoqAndChangedOriginalCannotDisagreeSilently(){var previous=PartnerCatalogFields.normalize(Map.of(),Map.of("moqQuantity","20"),true);assertThrows(RuntimeException.class,()->PartnerCatalogFields.normalize(previous,Map.of("moq","100个/每型号"),true));}
 @Test void scientificNotationCannotAllocateUnboundedMemory(){assertThrows(RuntimeException.class,()->PartnerCatalogFields.normalize(Map.of(),Map.of("moqQuantity","1e1000000000"),true));assertThrows(RuntimeException.class,()->PartnerCatalogFields.normalize(Map.of(),Map.of("moqQuantity","1e-1000000000"),true));}
 @Test void explicitQuantityClearDoesNotReappearFromOriginalTextDuringARead(){var first=PartnerCatalogFields.normalize(Map.of(),Map.of("moq","20个/每型号每颜色"),true);var cleared=PartnerCatalogFields.normalize(first,Map.of("moqQuantity",""),false);assertEquals("",cleared.get("moqQuantity"));assertEquals("explicit_empty",cleared.get("moqSource"));var stored=new LinkedHashMap<>(first);stored.putAll(cleared);stored.put("moq","20个/每型号每颜色");assertEquals("",PartnerCatalogFields.project(stored).get("moqQuantity"));assertEquals("20个/每型号每颜色",map(cleared.get("rawQuoteFields")).get("moq"));}
 @Test void explicitlyClearedAmbiguousMoqNoteStaysEmptyButUnstructuredHistoryStillDerivesANote(){var previous=PartnerCatalogFields.normalize(Map.of(),Map.of("moq","混款另议"),true);previous.put("moq","混款另议");var cleared=PartnerCatalogFields.normalize(previous,Map.of("moqNote",""),false);assertEquals("",cleared.get("moqNote"));var stored=new LinkedHashMap<>(previous);stored.putAll(cleared);assertEquals("",PartnerCatalogFields.project(stored).get("moqNote"));assertEquals("混款另议",PartnerCatalogFields.project(Map.of("moq","混款另议")).get("moqNote"));}
 @Test void editingAnUnrelatedFieldDoesNotInventAnEmptyPriceInsideExistingRawEvidence(){var evidence=Map.of("moq","20个/每型号","currency","");var previous=Map.<String,Object>of("rawQuoteFields",evidence,"unitPrice","","currency","CNY","currencySource","business_default");assertEquals(evidence,PartnerCatalogFields.normalize(previous,Map.of("moqQuantity",""),false).get("rawQuoteFields"));}
}
